246	        }
247	        if (owner.isNew() && owner.getNamesakeCount() == null) {
248	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
249	        }
250	        if (owner.isNew() && owner.getMembershipNumber() == null) {
251	            owner.setMembershipNumber(
252	                membershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
253	        }
254	        if (owner.isNew() && owner.getHouseholdSize() == null) {
255	            owner.setHouseholdSize(countHouseholdMembers(owner));
256	        }
257	        ownerRepository.save(owner);
