306	        return (int) ownerRepository.findAll().stream()
307	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
308	                && equalsIgnoreCase(existing.getLastName(), lastName))
309	            .count();
310	    }
