345	        String householdId = owner.getHouseholdId();
346	        if (householdId == null) {
347	            return null;
348	        }
349	        return ownerRepository.findAll().stream()
350	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
351	            .findFirst()
352	            .orElse(null);
353	    }
